def get_x_k(n, k_max):
    x = []
    T = 0
    fact = 1
    for k in range(1, k_max + 1):
        fact *= k
        if k == 1:
            T = 1
        else:
            T = k * T + k**(n-1)
        x.append((-T) % fact)
    return x

for n in [2, 5, 8]:
    print(f"n={n}: {get_x_k(n, 10)}")

for n in [1, 4, 7]:
    print(f"n={n}: {get_x_k(n, 10)}")

